		{
			code: `
				This is a sentence.
				This is another.
			`,
		},
		{
			code: `This is a \${myVar}`,
		},
	],
	invalid: [
		{
			code: 'var str = \\`abc\\`;',
			errors: [{ messageId: 'noUnnededBackticks' }],
			output: "var str = 'abc';",
		},
		{
			code: "var str = `abc 'def' ghi`;",
			errors: [{ messageId: 'noUnnededBackticks' }],
			output: 'var str = \'abc "def" ghi\';',
		},
	],
});
```

